// Когда-то здесь лежали декларации всех серверных env-переменных — «единая
// точка правды» по списку. Теперь она в bot/config.ts: слайсы типизированы,
// и опечатка в имени переменной ловится tsc в месте потребления. Декларации
// убраны, чтобы список не дублировался в двух местах (а толку от них было
// немного: индексная сигнатура ProcessEnv от @types/node всё равно оставалась,
// и компилятор опечатки не ловил — только IDE-подсказки).
//
// Осталась только PORT: её читает vite.config.ts, а сборке фронта знать про
// bot/config.ts не нужно. Профиль установки — .env.example, значения —
// env Vercel / .env.local.

export {};

declare global {
  namespace NodeJS {
    interface ProcessEnv {
      /** Порт vite в dev (читает vite.config.ts) */
      PORT?: string;
    }
  }
}
